        body{--base:#062d28;--glow:#236659;--accent:#dfc389;--panel:color-mix(in srgb,var(--base) 86%,var(--glow) 14%);--panel-edge:color-mix(in srgb,var(--glow) 38%,var(--base));--prayer-cols:7;margin:0;background:var(--base);color:#f7f7ee;font-family:system-ui,sans-serif;font-size:clamp(16px,1.55vw,32px);overflow:hidden}
