        body[data-theme=midnight]{--base:#0b1428;--glow:#293b64}body[data-theme=sand]{--base:#35291c;--glow:#836b43}body[data-theme=royal]{--base:#201539;--glow:#67468b}body[data-theme=ocean]{--base:#052b3c;--glow:#136480}body[data-theme=maroon]{--base:#321521;--glow:#783447}body[data-theme=olive]{--base:#222b16;--glow:#606c35}body[data-theme=slate]{--base:#172431;--glow:#475f72}
        #decoration{position:fixed;inset:0;z-index:-1;overflow:hidden;background:radial-gradient(ellipse at 15% 0%,var(--glow),transparent 70%),linear-gradient(150deg,transparent,#0007)}
        #decoration:before{content:"";position:absolute;inset:-20%;background:radial-gradient(ellipse at 75% 30%,#ffffff0c,transparent 45%);animation:ambient 24s ease-in-out infinite alternate}
        #decoration:after{content:"";position:absolute;bottom:0;left:0;width:100%;height:45%;opacity:.16;background:linear-gradient(transparent,#000);clip-path:polygon(0 100%,0 75%,12% 75%,12% 35%,13% 25%,14% 35%,14% 75%,30% 75%,30% 55%,35% 55%,35% 35%,40% 20%,45% 35%,45% 55%,50% 55%,50% 75%,78% 75%,78% 40%,79% 30%,80% 40%,80% 75%,100% 75%,100% 100%)}
        body[data-decoration=none] #decoration:after{display:none}body[data-decoration=clouds] #decoration:after{clip-path:none;bottom:30%;height:30%;width:140%;left:-20%;background:radial-gradient(ellipse at 25% 60%,#ffffff45,transparent 35%),radial-gradient(ellipse at 70% 70%,#ffffff35,transparent 40%);animation:clouds 40s ease-in-out infinite alternate}
        main{height:100vh;height:100dvh;padding:1.4vw 2vw;display:grid;grid-template-rows:auto minmax(0,1fr) auto;gap:1.2vw}
        header{display:flex;justify-content:space-between;align-items:center;gap:2vw;border-bottom:1px solid #ffffff30;padding-bottom:1vw}.identity{display:flex;align-items:center;gap:1.2vw;min-width:0}.identity>div{min-width:0}#logo{width:5.5vw;height:5.5vw;min-width:48px;min-height:48px;object-fit:contain;background:#fffffff0;border-radius:16px;padding:.4vw}h1{font-size:1.65em;line-height:1.15;margin:0;overflow-wrap:anywhere}#clock,#mode-clock{font-variant-numeric:tabular-nums;font-size:2.5em;line-height:1;font-weight:700;white-space:nowrap;color:var(--accent)}#date{margin-top:.4em;font-size:.7em}
        #body{display:grid;grid-template-columns:minmax(0,1fr);min-height:0;gap:1.2vw}body[data-layout=split][data-activities="1"] #body{grid-template-columns:minmax(0,3fr) minmax(220px,1fr)}#media{min-height:0;position:relative;display:flex;align-items:center;justify-content:center;background:#0004;border:1px solid #ffffff15;border-radius:20px;overflow:hidden}#media img,#media iframe{width:100%;height:100%;position:absolute;inset:0;object-fit:contain;border:0;animation:slide-in var(--transition-ms,800ms) ease both}#fallback{max-height:100%;overflow:auto;padding:2vw;text-align:center;white-space:pre-wrap;overflow-wrap:anywhere;font-size:1.4em}aside{display:none;background:#ffffff0b;padding:1.3vw;border-radius:20px;overflow:auto}body[data-layout=split][data-activities="1"] aside{display:block}h2{font-size:.75em;margin:0 0 .6em;color:var(--accent)}#activities{font-size:.8em;overflow-wrap:anywhere}#activities p{margin:0 0 1em;padding-bottom:1em;border-bottom:1px solid #ffffff24}
        footer{background:#ffffff0b;border:1px solid #ffffff1c;border-radius:18px;overflow:hidden}.prayer-strip{padding:.7vw 1.2vw}#prayers{display:flex;justify-content:space-around;gap:1vw}#prayers>div{display:flex;align-items:center;justify-content:center;gap:1vw;flex:1;padding:.55vw;border-radius:10px;border:1px solid transparent}#prayers span{font-size:.85em}#prayers strong{font-variant-numeric:tabular-nums;color:var(--accent)}#prayers .current{background:#ffffff12;border-color:#ffffff30}#prayers .upcoming{background:var(--accent);color:var(--base);box-shadow:0 0 24px #0002}#prayers .upcoming strong{color:inherit}
        #announcement-window{overflow:hidden;background:#0003;border-top:1px solid #ffffff1c;padding:.55em 0;font-size:1.35em;font-weight:600}body[data-announcement-size=normal] #announcement-window{font-size:1em}body[data-announcement-size=extra] #announcement-window{font-size:1.7em}#announcement{display:inline-block;white-space:nowrap;padding-left:100%;animation:announcement var(--announcement-seconds,40s) linear infinite}#status{display:flex;justify-content:space-between;gap:1em;font-size:.55em;opacity:.7;margin-top:.5vw}#preview{font-size:.6em;color:var(--accent)}#tv-tools{position:fixed;right:1vw;top:1vw;z-index:5;font-size:14px;text-align:right}#fullscreen{background:#132c30;color:#fff;border:1px solid #ffffff50;border-radius:8px;padding:.5em .8em}#fullscreen-message{max-width:24em;background:#0009}html:fullscreen #tv-tools{opacity:0}html:fullscreen #tv-tools:hover,html:fullscreen #tv-tools:focus-within{opacity:1}
        #prayer-mode{display:none;position:fixed;inset:0;background:radial-gradient(ellipse at top,var(--glow),var(--base) 80%);align-items:center;justify-content:center;flex-direction:column;text-align:center;gap:3vh;padding:5vw}body[data-mode=adhan] main,body[data-mode=iqamah] main,body[data-mode=prayer] main{display:none}body[data-mode=adhan] #prayer-mode,body[data-mode=iqamah] #prayer-mode,body[data-mode=prayer] #prayer-mode{display:flex}body:not([data-mode=normal]) #tv-tools{display:none}#mode-title{font-size:clamp(28px,5vw,100px);font-weight:600}#mode-countdown{font-size:clamp(60px,12vw,230px);font-variant-numeric:tabular-nums;font-weight:700;color:var(--accent)}#mode-note{font-size:1.1em;opacity:.7}#mode-clock{font-size:clamp(28px,4vw,80px)}
        body[data-mode=prayer] #prayer-mode{background:#05080b;isolation:isolate}body[data-mode=prayer] #prayer-mode:before{content:"";position:absolute;inset:0;z-index:-1;background:radial-gradient(ellipse at 30% 40%,#142028,transparent 65%);opacity:.3;animation:ambient 28s ease-in-out infinite alternate}body[data-mode=prayer] #mode-title,body[data-mode=prayer] #mode-countdown,body[data-mode=prayer] #mode-note{display:none}body[data-mode=prayer] #mode-clock{font-size:clamp(70px,13vw,260px);font-weight:300;color:#b3b9bc}
        @keyframes announcement{from{transform:translateX(0)}to{transform:translateX(-100%)}}@keyframes slide-in{from{opacity:0;transform:translateY(1.2%)}to{opacity:1;transform:none}}@keyframes ambient{from{transform:scale(1);opacity:.25}to{transform:scale(1.12);opacity:.4}}@keyframes clouds{from{transform:translateX(-3%)}to{transform:translateX(3%)}}
        @media(max-width:700px){main{padding:0;gap:0}header{padding:.4vmin .75vmin .3vmin;gap:8px}h1{font-size:1.15em}#clock{font-size:clamp(1.15rem,6vmin,8vh)}.header-center{max-width:38%}.status-badge{font-size:.4em}.status-meta,#updated{font-size:.38em}#body{padding:.45vmin .75vmin 0}#prayers>div{flex-direction:column;gap:2px;padding:6px 1px}#prayers span{font-size:.68em}#prayers strong{font-size:1.25em}body[data-layout=split][data-activities="1"] #body{grid-template-columns:minmax(0,1fr)}body[data-layout=split][data-activities="1"] aside{display:none}}
        body:not([data-mode=normal]) #announcement{animation-play-state:paused}
        @media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}#announcement{padding:0 1em;white-space:normal;overflow-wrap:anywhere}#announcement-window{max-height:20vh;overflow:auto}body[data-mode=prayer] #mode-clock{filter:none}}
        html,body{width:100%;height:100%;min-width:0;min-height:0}
        body{font-size:clamp(9px,2.4vmin,30px)}
        main{width:100%;height:100dvh;padding:0;gap:0;grid-template-rows:auto minmax(0,1fr) auto}
        main>*{min-width:0;min-height:0}
        header{align-self:stretch;display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,auto);align-items:start;gap:1.2vmin 1.5vmin;padding:.45vmin .9vmin .35vmin;margin:0;overflow:hidden;border-bottom:2px solid color-mix(in srgb,var(--accent) 75%,transparent);background:linear-gradient(118deg,var(--panel),var(--panel-edge));border-radius:0}
        .identity{gap:1.6vmin;overflow:hidden;min-width:0;justify-self:start;align-self:center}
        .header-center{align-self:start;justify-self:center;min-width:0;max-width:min(46vw,28em);padding:.05vmin .5vmin 0;display:flex;flex-direction:column;align-items:center;gap:.18em}
        .status-badge{padding:.28em .75em;border-radius:.65vmin;font-size:.42em;font-weight:700;letter-spacing:.03em;line-height:1.2;border:1px solid color-mix(in srgb,var(--accent) 40%,#ffffff30);background:color-mix(in srgb,var(--glow) 22%,var(--base));color:#f7f7ee;max-width:100%}
        .status-badge[data-state=online]{border-color:color-mix(in srgb,var(--accent) 65%,#86efac);background:color-mix(in srgb,var(--glow) 45%,var(--base));color:color-mix(in srgb,var(--accent) 25%,#fff)}
        .status-badge[data-state=offline]{border-color:color-mix(in srgb,#fbbf24 55%,var(--accent));background:color-mix(in srgb,#78350f 28%,var(--base));color:#fef3c7}
        .status-badge[data-state=pending]{border-color:color-mix(in srgb,var(--accent) 35%,#ffffff40);opacity:.92}
        .status-meta,#updated{font-size:.4em;font-weight:500;line-height:1.25;opacity:.82;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:center;letter-spacing:.02em}
        #logo{width:8vmin;height:8vmin;min-width:0;min-height:0;flex-shrink:0;border-radius:1.2vmin;padding:.5vmin}
        h1{font-size:1.35em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
        .header-time{align-self:center;justify-self:end;display:flex;flex-direction:column;align-items:flex-end;gap:.1em;min-width:0;text-align:right}
        #clock{font-variant-numeric:tabular-nums;font-size:clamp(1.35rem,7.4vmin,10vh);line-height:.95;font-weight:700;white-space:nowrap;color:var(--accent)}#date{font-size:.58em;margin-top:.12em;opacity:.88;line-height:1.2}#preview{font-size:.46em;font-weight:600;line-height:1.25;margin-top:.15em}
        #connection{display:block;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
        #body{gap:.55vmin;padding:.55vmin .9vmin 0;min-height:0}#media{container-type:size;border-radius:1.4vmin;min-width:0;background:#000}
        #media img{object-fit:contain;animation-name:slide-in}
        body[data-media-fit=cover] #media img{object-fit:cover}
        #media iframe{inset:auto;left:50%;top:50%;transform:translate(-50%,-50%);width:100%;height:100%;animation-name:video-in}
        @supports(width:1cqw){
            #media iframe{width:min(100cqw,177.7778cqh);height:min(100cqh,56.25cqw)}
            body[data-media-fit=cover] #media iframe{width:max(100cqw,177.7778cqh);height:max(100cqh,56.25cqw)}
        }
        aside{padding:1.5vmin;border-radius:1.4vmin}
        .footer-frame{position:relative;display:flex;flex-direction:column;overflow:hidden;height:auto;align-self:stretch;margin:0}
        footer{height:auto;min-height:0;display:flex;flex-direction:column;justify-content:flex-end;border-radius:0;border:0;border-top:2px solid color-mix(in srgb,var(--accent) 75%,transparent);background:linear-gradient(118deg,var(--panel-edge),var(--panel))}
        .prayer-strip{padding:.35vmin .75vmin 0;flex:0 0 auto;min-height:0;display:flex;align-items:stretch;gap:0}
        .prayer-label{flex:0 0 auto;width:min(10.5em,13vmin);display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;gap:.12em;padding:.1vmin .45vmin;border-right:1px solid color-mix(in srgb,var(--accent) 25%,#ffffff28)}
        #prayer-heading{margin:0;font-size:.64em;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);line-height:1.15}
        #prayer-location{margin:0;font-size:.54em;line-height:1.2;opacity:.88;max-width:100%;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;word-break:break-word}
        #prayer-location:empty{display:none}
        #prayers{flex:1;min-width:0;display:grid;grid-template-columns:repeat(var(--prayer-cols,7),minmax(0,1fr));gap:0;font-size:.86em}
        #prayers>div{min-width:0;flex-direction:column;gap:.08vmin;padding:.32vmin .12vmin;border-radius:0;border:0;border-left:1px solid color-mix(in srgb,var(--accent) 22%,#ffffff25);background:transparent}
        #prayers>div:first-child{border-left:0}
        #prayers span{font-size:.74em;letter-spacing:.03em}#prayers strong{font-size:1.48em;line-height:1.02;color:var(--accent)}
        #prayers .extra{opacity:.88}#prayers .extra strong{color:color-mix(in srgb,var(--accent) 70%,#fff)}
        #prayers .current{background:color-mix(in srgb,var(--accent) 14%,#ffffff10);box-shadow:inset 0 -.22vmin 0 var(--accent)}
        #prayers .upcoming{background:var(--accent);color:var(--base);box-shadow:inset 0 -.28vmin 0 color-mix(in srgb,var(--base) 35%,#000)}
        #prayers .upcoming span,#prayers .upcoming strong{color:inherit}
        #announcement-window{flex-shrink:0;margin-top:0;padding:.18em 0 0;font-size:1em;line-height:1.12;border-top:1px solid color-mix(in srgb,var(--accent) 20%,#ffffff1c)}
        body[data-announcement-size=normal] #announcement-window{font-size:.9em}body[data-announcement-size=extra] #announcement-window{font-size:1.3em}
        body[data-layout=immersive] main{padding:0;gap:0;position:relative;isolation:isolate}
        body[data-layout=immersive] header{position:absolute;inset:0 1.1vmin auto;height:auto;z-index:2;padding:.35vmin 2vmin 0;border:1px solid color-mix(in srgb,var(--accent) 28%,#ffffff35);border-bottom:2px solid color-mix(in srgb,var(--accent) 75%,transparent);border-radius:0 0 1.8vmin 1.8vmin;background:linear-gradient(118deg,var(--panel),var(--panel-edge));pointer-events:none;text-shadow:0 2px 5px #000}
        body[data-layout=immersive] .footer-frame{position:absolute;inset:auto 1.1vmin 0;height:auto;z-index:2;padding:0;background:none;overflow:visible;pointer-events:none;text-shadow:0 2px 5px #000}
        body[data-layout=immersive] footer{background:linear-gradient(118deg,var(--panel-edge),var(--panel));border:1px solid color-mix(in srgb,var(--accent) 28%,#ffffff35);border-top:2px solid color-mix(in srgb,var(--accent) 75%,transparent);border-radius:1.8vmin 1.8vmin 0 0}
        body[data-layout=immersive] aside{display:none}
        body[data-layout=immersive] #body{position:absolute;inset:0;padding:0;grid-template-columns:minmax(0,1fr);z-index:0}
        body[data-layout=immersive] #media{border:0;border-radius:0}
        body[data-layout=immersive] .header-center{max-width:min(40vw,22em)}
        body[data-layout=immersive] .status-badge,body[data-layout=immersive] .status-meta,body[data-layout=immersive] #updated{text-shadow:0 1px 3px #000}body[data-theme=daylight][data-layout=immersive] .status-badge,body[data-theme=daylight][data-layout=immersive] .status-meta,body[data-theme=daylight][data-layout=immersive] #updated,body[data-theme=daylight][data-layout=immersive] #clock{text-shadow:none}
        #media-message{position:absolute;z-index:1;left:5%;right:5%;bottom:5%;padding:1vmin 2vmin;background:#000d;color:#fff;text-align:center;font-size:.7em;pointer-events:none;border-radius:1vmin}
        body[data-layout=immersive] #media-message{bottom:15%}
        #fallback{font-size:1em;padding:2vmin}
        #tv-tools{font-size:clamp(10px,1.5vmin,16px);top:1vmin;right:1vmin;opacity:.3}#tv-tools:hover,#tv-tools:focus-within{opacity:1}
        #mode-title{font-size:7vmin}#mode-countdown{font-size:18vmin}#mode-clock{font-size:7vmin}body[data-mode=prayer] #mode-clock{font-size:20vmin}
        @keyframes video-in{from{opacity:0}to{opacity:1}}
        @media(max-aspect-ratio:4/3){.prayer-label{display:none}body[data-layout=split][data-activities="1"] #body{grid-template-columns:minmax(0,1fr)}body[data-layout=split][data-activities="1"] aside{display:none}}
        body[data-layout=immersive] header{grid-template-columns:minmax(0,1fr) auto minmax(0,auto);align-items:start}
        .tv-scenery{position:absolute;inset:0;overflow:hidden;pointer-events:none}
        #decoration{z-index:0;pointer-events:none}main{position:relative;z-index:1}#prayer-mode{z-index:3;isolation:isolate;overflow:hidden}
        #decoration .tv-scenery{opacity:.96}#prayer-mode .tv-scenery{z-index:-1}
        .scene-stars{position:absolute;inset:0;background-image:radial-gradient(circle,#fffc 1px,transparent 1.5px),radial-gradient(circle,#dfc389cc 1.2px,transparent 1.8px);background-size:11vmin 13vmin,19vmin 23vmin;background-position:2vmin 3vmin,8vmin 9vmin;opacity:.48}
        .scene-moon{position:absolute;width:17vmin;height:17vmin;border-radius:50%;right:12%;top:13%;background:var(--accent);opacity:.62;mask:radial-gradient(circle at 65% 35%,transparent 58%,#000 60%);-webkit-mask:radial-gradient(circle at 65% 35%,transparent 58%,#000 60%)}
        .scene-mosque{position:absolute;bottom:0;left:-2%;width:104%;height:48%;background:linear-gradient(#1a4a42dd,#0a1816);opacity:.84;clip-path:polygon(0 100%,0 75%,10% 75%,10% 30%,11% 18%,12% 30%,12% 75%,29% 75%,29% 62%,36% 62%,36% 43%,40% 30%,44% 43%,44% 62%,51% 62%,51% 75%,73% 75%,73% 27%,74% 15%,75% 27%,75% 75%,91% 75%,91% 58%,95% 44%,99% 58%,99% 75%,100% 75%,100% 100%)}
        .scene-clouds{position:absolute;inset:5% -15% 35%;background:radial-gradient(ellipse at 20% 50%,#ffffff55,transparent 34%),radial-gradient(ellipse at 65% 65%,#ffffff42,transparent 38%);animation:clouds 50s ease-in-out infinite alternate;opacity:.95}
        .scene-dunes{position:absolute;left:-10%;right:-10%;bottom:-7%;height:38%;background:linear-gradient(170deg,#d4a55faa,#4a3524);border-radius:55% 70% 0 0;transform:rotate(-5deg);opacity:.86}
        .scene-dunes:after{content:"";position:absolute;inset:23% -5% -10%;border-radius:65% 45% 0 0;background:linear-gradient(170deg,#9a7340,#2a211c);transform:rotate(10deg)}
        .scene-lanterns{position:absolute;top:0;left:15%;width:8vmin;height:25vmin;background:linear-gradient(90deg,transparent 48%,var(--accent) 49% 51%,transparent 52%);opacity:.78}
